// Liệt kê đầy đủ method không dùng tham số cho MỘT file (bản sao logic
// của scripts/scan-unused-params.mjs nhưng không cắt 40 dòng).
// Dùng: node node_modules/.verify-tmp/list-findings.mjs <đường dẫn file>
import fs from 'node:fs';
import path from 'node:path';

const target = process.argv[2];
if (!target) {
  console.error('Thiếu đường dẫn file');
  process.exit(1);
}

function extractMethods(src) {
  const methods = [];
  const re = /^[ \t]*public\s+([A-Za-z_$][\w$]*)\s*(?:<[^>]*>)?\s*\(([^)]*)\)\s*:\s*([^{]+?)\s*\{\s*$/gm;
  let m;
  while ((m = re.exec(src)) !== null) {
    const braceOffset = m[0].lastIndexOf('{');
    const bodyStart = m.index + braceOffset;
    let depth = 0;
    let i = bodyStart;
    for (; i < src.length; i++) {
      const ch = src[i];
      if (ch === '{') depth++;
      else if (ch === '}') {
        depth--;
        if (depth === 0) break;
      }
    }
    const body = src.slice(bodyStart + 1, i);
    const line = src.slice(0, m.index).split('\n').length;
    methods.push({ name: m[1], params: m[2].trim(), body, line });
  }
  return methods;
}

function splitTopLevel(raw) {
  const parts = [];
  let depth = 0;
  let current = '';
  for (const ch of raw) {
    if (ch === '<' || ch === '(' || ch === '[' || ch === '{') depth++;
    else if (ch === '>' || ch === ')' || ch === ']' || ch === '}') depth--;
    if (ch === ',' && depth === 0) {
      parts.push(current);
      current = '';
      continue;
    }
    current += ch;
  }
  if (current.trim()) parts.push(current);
  return parts;
}

function paramNames(raw) {
  if (!raw.trim()) return [];
  return splitTopLevel(raw).map((p) => {
    const name = p.split('=')[0].split(':')[0].trim();
    return name.replace(/^\.\.\./, '').replace(/[?]/g, '');
  });
}

const src = fs.readFileSync(target, 'utf8');
let count = 0;
for (const meth of extractMethods(src)) {
  const names = paramNames(meth.params);
  if (names.length === 0) continue;
  const body = meth.body
    .replace(/\/\/[^\n]*/g, ' ')
    .replace(/\/\*[\s\S]*?\*\//g, ' ');
  const unused = names.filter((name) => {
    if (!name || name === 'this') return false;
    const re = new RegExp(`\\b${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`);
    return !re.test(body);
  });
  if (unused.length > 0) {
    count++;
    console.log(`L${String(meth.line).padStart(5)}  ${meth.name}(${meth.params})  -> khong dung: ${unused.join(', ')}`);
  }
}
console.log(`\nTONG: ${count} method`);
